@startuml

class Sensor {
  + vendorId : string
  + description : string
  + unit : string
}

class TemperatureSensor {
  + minValue : double
  + maxValue : double
}

class PowerSensor {}

class Room {
  + description : string
}

class Apartment {
  + address : string
}

class User {
  + username : string
  + password : string
}

class SensorController {
  "1" *-- "*" Sensor
  "1" *-- "*" Room
  "0..1" -- "*" Apartment
  "1" *-- "*" User
}

class EMonitor {}

enum Unit {
  CELSIUS
  WATT
}

Sensor "1" *-- "1 room" Room
TemperatureSensor --|> Sensor
PowerSensor --|> Sensor
Apartment "1" *-- "* rooms" Room
User "0..*" -- "*" Apartment

EMonitor "1" *-- "*" SensorController

@enduml

